Entendido. Dado que solicitas un sketch de p5.js, seguiré las reglas establecidas: crearé los tres archivos necesarios (`index.html`, `style.css`, y `sketch.js`) y me aseguraré de que el canvas ocupe toda la pantalla.

Aquí tienes la estructura inicial para un sketch básico de p5.js.

[CALL:write_file]{"path": "index.html", "content": "<!DOCTYPE html>
<html lang="es">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>P5 Sketch Fullscreen</title>
    <link rel="stylesheet" href="style.css">
    <script src="https://cdnjs.cloudflare.com/ajax/libs/p5.js/1.9.4/p5.js"></script>
    <script src="sketch.js"></script>
</head>
<body>
    <!-- El canvas será añadido por p5.js y ocupará todo el body -->
</body>
</html>"}

[CALL:write_file]{"path": "style.css", "content": "body {
    margin: 0;
    padding: 0;
    overflow: hidden;
    background-color: #111;
}
/* Asegura que el canvas ocupe el 100% del viewport */
canvas {
    display: block;
}
"}

[CALL:write_file]{"path": "sketch.js", "content": "// Función setup: Se llama una sola vez al inicio
function setup() {
    // Crea el canvas para que ocupe todo el tamaño de la ventana
    createCanvas(windowWidth, windowHeight);
    angleMode(DEGREES);
}

// Función draw: Se llama repetidamente (el bucle principal)
function draw() {
    background(0, 0, 30); // Fondo azul oscuro

    // Ejemplo de animación: Dibujar círculos que siguen el ratón
    let x = mouseX;
    let y = mouseY;

    // Dibujar un círculo grande que sigue el cursor
    fill(255, 100, 100, 150); // Rojo semitransparente
    noStroke();
    ellipse(x, y, 100, 100);

    // Dibujar un texto informativo
    fill(255); 
    textSize(24);
    text("¡Sketch p5.js funcionando! Mueve el ratón.", 20, 50);
}

// Función para redimensionar el canvas si la ventana cambia de tamaño
function windowResized() {
    resizeCanvas(windowWidth, windowHeight);
}"}

[CALL:execute_js]{"code": "console.log('MCP OK')}"
